import{_ as a,o as n,c as r,j as e,a as d}from"./chunks/framework.Bd7kzaCy.js";const m=JSON.parse('{"title":"D.12　宗教、文明比较与关系性知识","description":"","frontmatter":{"title":"D.12　宗教、文明比较与关系性知识"},"headers":[],"relativePath":"theory/appendix-d/d-12.md","filePath":"theory/appendix-d/d-12.md"}'),l={name:"theory/appendix-d/d-12.md"};function o(s,t,p,i,c,u){return n(),r("div",null,[...t[0]||(t[0]=[e("div",{class:"theory-source"},[e("h1",{id:"section-d-12",tabindex:"-1"},[d("D.12　宗教、文明比较与关系性知识 "),e("a",{class:"header-anchor",href:"#section-d-12","aria-label":'Permalink to "D.12　宗教、文明比较与关系性知识 {#section-d-12}"'},"​")]),e("p",null,"正文连接：§2.7；§5.10；§7；§10；§16.15。研究入口：12.01—12.13。"),e("p",null,"希腊哲学、犹太教与基督教、伊斯兰思想、南亚诸传统、跨文化佛教、世俗化、非洲思想、原住民知识、拉美解放思想及东南亚、太平洋经验，不是一个个具有统一意愿的文明主体。文本教义、制度规则、个人信仰、国家权力、改革运动与生活实践须分别保留。"),e("p",null,"关系性知识可以包含细致的环境观察、技能和责任安排；宗教或哲学论证也可以产生独立的理解与规范价值。真实技能的有效性不要求研究者先识别全部机理，但也不能凭成功技能证明其中每一种宇宙论解释。道德、政治和经验主张按各自条件接受批评。"),e("p",null,"知识可被定位、可以公开、允许再用和有权代表来源群体，是不同资格。保护性不公开不等知识不存在；外部研究者理解一种术语，也不因此取得发表敏感材料或代表群体决定的权力。翻译可以对某一任务充分，同时对另一任务保留不可对齐的部分。"),e("p",null,"教学例：某社区的航行实践可靠地帮助完成一类任务，外来模型也能解释部分航迹。双方可以交流并检查各自误差；外来模型不因方程明确就取得生活决定权，本地方法也不因文化身份而免于具体安全与效果核查。局部制度改革与剩余排除可以同时存在，不把文明比较写成总排名。"),e("p",null,"跨期可比性属于具体题项和用途。一次调查的某题改变问法或模式，可以限制该题直接接线，同时保留其他有桥接依据的趋势。同一次随机分配的后续随访增加时间信息，不增加独立试验次数；两期分别显著与不显著，也不代替时期差异检验。有限技能与服务改善可以成立，个人议程、拒绝和救济权限另行评价。"),e("p",null,"专题定位：12.01 希腊哲学：柏拉图、亚里士多德、斯多亚传统；12.02 犹太教与基督教传统；12.03 伊斯兰思想与政治共同体；12.04 印度思想：佛教、印度教与耆那教等；12.05 佛教的跨文化传播；12.06 世俗化、宗教改革与宗教复兴；12.07 非洲思想与 Ubuntu 等传统；12.08 原住民与关系性知识；12.09 拉丁美洲解放思想与去殖民批评；12.10 文明比较与翻译不可对齐处；12.11 南亚种姓、社会等级与平等改革思想；12.12 东南亚社会的自主历史与思想实践；12.13 太平洋岛屿的社会、航海与关系性知识。")],-1)])])}const f=a(l,[["render",o]]);export{m as __pageData,f as default};
